<script setup lang="ts">
import {ref} from "vue";
import type {PageSummaryApi} from "../../../ai/usePageSummary";
import PageSummary from "../../ai/PageSummary.vue";
import ReadonlySelectionActions from "../../ai/ReadonlySelectionActions.vue";
import ChangeSummaryField from "../../publishing/ChangeSummaryField.vue";
import PublishControl from "../../publishing/PublishControl.vue";
import TagSuggestions from "../../creation/TagSuggestions.vue";
import SettingsSection from "../../settings/SettingsSection.vue";
import {Button} from "../../ui/button";
import {sources,sentences,provenance} from "./aiSampleData";
import {useStoryboard} from "./storyboard";
const root=ref<HTMLElement>();const {sleep}=useStoryboard(root);
const page=ref({id:"sample-page",version:1}),coverage=ref(true),enabled=ref(true),manual=ref(""),notice=ref(""),tags=ref<string[]>([]);
const summaryApi:PageSummaryApi={preparePageSummary:async()=>{await sleep(700);return{conversationId:"sample-c",messageId:"sample-m",state:"preparing",sources,truncated:coverage.value};},completeMessage:async()=>{await sleep(1300);return{id:"sample-m",conversationId:"sample-c",role:"assistant",state:"answered",sources,sentences,provenance,truncated:coverage.value,createdAt:new Date().toISOString()};},sendFeedback:async()=>{}};
async function proposal(){await sleep(900);return{text:"Doplněn postup pro připojení k VPN.",provenance,contextKey:"sample-page:"+page.value.version};}
async function tagProposal(){await sleep(900);return{tags:[{id:"sample-tag-1",name:"VPN"},{id:"sample-tag-2",name:"Návody"}],provenance};}
const selection=ref<{text:string;searchText:string;section?:string;anchorRect:DOMRect;sectionHref:string}|null>(null);
function select(){const rect=root.value!.querySelector('[data-reading-sample]')!.getBoundingClientRect();selection.value={text:"Notebook musí mít platný certifikát zařízení.",searchText:"Notebook musí mít platný certifikát zařízení.",section:"Certifikáty",anchorRect:rect,sectionHref:"#/pages/sample?heading=certifikaty"};}
</script>
<template><SettingsSection title="Čtení a publikace s modelem" description="PageSummary sdílí hrany stránky: akce i odpověď jsou v jeho čtecí šířce. Nabízí nenápadnou akci nad stránkou a rozbalí AiAnswer; při zavírání ponechá obsah do konce rychlého přechodu. Odlišuje se od odpovědi hledání účelem, odrážkami a upozorněním na rozsah. ReadonlySelectionActions používá existující popover nad bezpečnou projekcí textu a textovou variantu CopyPageLink včetně ručního kopírování. Je to jediná lišta čtenáře stránky (bublina editoru pro čtenáře je tu vypnutá): začíná Kopírovat (potvrdí „Zkopírováno“), Alt+F10 do ní přesune fokus, šipky mezi akcemi, Esc ji skryje a výběr nechá. Kopírování a hledání fungují i při vypnutých schopnostech; Zeptat se, Vysvětlit a Shrnout (P11, assist/aiIntents.ts) potřebují AI a bez ní, nad samotným prvkem, nad tajemstvím nebo nad víc než 1 600 znaky nejsou vidět, ostatní akce lišty zůstanou. Výběr v nadpisu (i trojklik) ukazuje na celou jeho sekci a lišta ji viditelně jmenuje („Sekce „Certifikáty““ před Zeptat se); když je sekce delší než limit, vezme se jen vybraný text. ChangeSummaryField a TagSuggestions skládají SuggestionChip: návrh není uložená hodnota, Použít je výslovné. Publikace na model nečeká. Ukázka používá skutečné komponenty s místními callbacky, bez serverových požadavků."><div ref="root" class="reading-writing-example" data-atlas-motion><div class="rwe-controls"><Button size="sm" variant="outline" @click="page.version++">Změnit verzi</Button><Button size="sm" variant="outline" @click="enabled=!enabled">{{enabled?'Vypnout schopnosti':'Zapnout schopnosti'}}</Button><Button size="sm" variant="outline" @click="coverage=!coverage">{{coverage?'Omezené pokrytí':'Úplné pokrytí'}}</Button></div><div class="document-body rwe-article"><PageSummary :page="page" :enabled="enabled" :api="summaryApi" @open-source="notice='Citace otevře příslušný nadpis.'" /><p data-reading-sample>Notebook musí mít platný certifikát zařízení.</p></div><Button size="sm" variant="outline" @click="select">Ukázat akce výběru</Button><ReadonlySelectionActions :selection="selection" :enabled="true" :explain-enabled="enabled" @explain="notice='Bezpečný výběr přejde do Asistenta s rozsahem Tato stránka.';selection=null" @find="notice='Text výběru přejde do běžného hledání.';selection=null" @close="selection=null" /><ChangeSummaryField :record-interaction="()=>{}" v-model="manual" :context-key="'sample-page:'+page.version" :suggest="enabled?proposal:undefined" /><PublishControl :summary-interaction="()=>{}" :publish="async text=>{notice=text?'Publikováno s popisem: '+text:'Publikováno.';return true;}" :suggest-summary="enabled?proposal:undefined" :summary-context-key="'sample-page:'+page.version" /><TagSuggestions :record-interaction="()=>{}" :context-key="'sample-page:'+page.version" :request="enabled?tagProposal:undefined" @apply="tags=$event.map(tag=>tag.name)" /><p v-if="tags.length">Tagy v místním konceptu: {{tags.join(', ')}}</p><p v-if="notice" role="status">{{notice}}</p></div></SettingsSection></template>
<style scoped>.reading-writing-example {display:grid;gap:14px;min-width:0;} .rwe-controls {display:flex;gap:8px;flex-wrap:wrap;} .reading-writing-example p {margin:0;color:var(--muted);} .rwe-article > p {width:calc(100% - 80px);max-width:740px;margin-inline:auto;} @media(max-width:899px){.rwe-article > p {width:calc(100% - 40px);}} .reading-writing-example :deep(.publish-control) {justify-self:start;}</style>
